// Title: Convert Excel WordArt with gradient fill to PDF and embed a PNG fallback image using Aspose.Cells for .NET
// Common Searches: Aspose.Cells preserve WordArt gradient when exporting Excel to PDF in C# | How to add a raster PNG fallback for WordArt in PDFs generated by Aspose.Cells | C# code to generate a PNG from a WordArt shape and embed it before saving as PDF | Export Excel workbook with WordArt to PDF/A-1b using Aspose.Cells and include a fallback image | Create temporary workbook to render WordArt as PNG for PDF fallback in Aspose.Cells
// Tags: gradient WordArt PDF conversion Aspose.Cells | fallback raster image for WordArt PDF | Aspose.Cells PdfSaveOptions PDF/A-1b compliance | generate PNG from WordArt shape C# | embed picture as fallback layer in worksheet

using System;
using System.IO;
using System.Drawing;
using Aspose.Cells;
using Aspose.Cells.Drawing;
using Aspose.Cells.Rendering;

namespace WordArtPdfDemo
{
    // The example creates an Excel workbook, adds a WordArt shape with a gradient style, generates a matching PNG fallback image, inserts the PNG into the worksheet, and saves the workbook as a PDF/A‑1b document using Aspose.Cells PdfSaveOptions.
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // Paths for output files
                string outputPdf = "WordArtWithFallback.pdf";
                string fallbackImagePath = Path.Combine(Path.GetTempPath(), "WordArtFallback.png");

                // -----------------------------------------------------------------
                // 1. Create a workbook and add a worksheet
                // -----------------------------------------------------------------
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // -----------------------------------------------------------------
                // 2. Add WordArt
                // -----------------------------------------------------------------
                Shape wordArt = sheet.Shapes.AddWordArt(
                    PresetWordArtStyle.WordArtStyle1,
                    "Gradient WordArt",
                    2,   // topRow
                    10,  // top (pixels)
                    2,   // leftColumn
                    10,  // left (pixels)
                    100, // height (pixels)
                    300  // width (pixels)
                );

                // Optional text formatting
                wordArt.TextEffect.FontSize = 24;
                wordArt.TextEffect.FontBold = true;

                // -----------------------------------------------------------------
                // 3. Create a raster fallback image that mimics the WordArt appearance
                // -----------------------------------------------------------------
                CreateFallbackImage(fallbackImagePath, "Gradient WordArt", 300, 100);

                // Add the raster image to the worksheet as a picture (if the file was created)
                if (File.Exists(fallbackImagePath))
                {
                    sheet.Pictures.Add(2, 10, fallbackImagePath);
                }

                // -----------------------------------------------------------------
                // 4. Prepare PDF save options
                // -----------------------------------------------------------------
                PdfSaveOptions pdfOptions = new PdfSaveOptions
                {
                    Compliance = PdfCompliance.PdfA1b,
                    OnePagePerSheet = true
                };

                // -----------------------------------------------------------------
                // 5. Save the workbook as PDF
                // -----------------------------------------------------------------
                workbook.Save(outputPdf, pdfOptions);
                Console.WriteLine($"PDF saved to: {Path.GetFullPath(outputPdf)}");
                Console.WriteLine($"Fallback raster image used: {fallbackImagePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }

        // Generates a simple PNG containing the same WordArt using Aspose.Cells only.
        private static void CreateFallbackImage(string filePath, string text, int width, int height)
        {
            try
            {
                // Create a temporary workbook with the WordArt
                Workbook tempWb = new Workbook();
                Worksheet tempSheet = tempWb.Worksheets[0];

                // Add WordArt that fits the desired image size
                Shape tempWordArt = tempSheet.Shapes.AddWordArt(
                    PresetWordArtStyle.WordArtStyle1,
                    text,
                    0,   // topRow
                    0,   // top
                    0,   // leftColumn
                    0,   // left
                    height,
                    width
                );

                // Optional text formatting for the fallback image
                tempWordArt.TextEffect.FontSize = 24;
                tempWordArt.TextEffect.FontBold = true;

                // Save as PNG
                tempWb.Save(filePath, SaveFormat.Png);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to create fallback image: {ex.Message}");
            }
        }
    }
}
